import { useState } from "react";
import C from "../constants/colors";
import { MARKET_DATA } from "../constants/data";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import TrendPill from "../components/ui/TrendPill";

function MarketPrices() {
  const [cat, setCat] = useState("All");
  const [search, setSearch] = useState("");
  const cats = ["All","Vegetable","Cereal","Pulse","Oilseed","Cash Crop","Fruit","Flower","Spice","Plantation"];
  const filtered = MARKET_DATA.filter(p => (cat==="All"||p.category===cat) && (!search||p.crop.toLowerCase().includes(search.toLowerCase())));
  return (
    <div style={{ padding:22 }}>
      <h1 style={{ fontSize:21, fontWeight:600, color:C.text, margin:"0 0 4px" }}>📈 Agri Market Prices</h1>
      <p style={{ color:C.muted, fontSize:13, margin:"0 0 14px" }}>42 crops • Real Agmarknet data • Madurai & Tamil Nadu mandis • Updated today 08:30 AM</p>

      <div style={{ display:"flex", gap:8, marginBottom:12, flexWrap:"wrap", alignItems:"center" }}>
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search crop…"
          style={{ padding:"8px 12px", borderRadius:8, border:`1px solid ${C.border}`, fontSize:13, outline:"none", width:200 }} />
        {cats.map(c => <button key={c} onClick={()=>setCat(c)} style={{ padding:"6px 13px", borderRadius:16, fontSize:12.5, cursor:"pointer", border:`1.5px solid ${cat===c?C.bg2:C.border}`, background:cat===c?C.pale:C.white, color:cat===c?C.bg2:C.muted, fontWeight:cat===c?600:400 }}>{c}</button>)}
      </div>

      <Card style={{ padding:0, overflow:"hidden", marginBottom:14 }}>
        <div style={{ display:"grid", gridTemplateColumns:"1.8fr 1fr 1fr 1fr 0.8fr 1fr", padding:"9px 14px", background:C.pale, fontSize:11.5, fontWeight:600, color:C.text, borderBottom:`1px solid ${C.border}` }}>
          <span>Crop</span><span>₹/Quintal (Modal)</span><span>Low</span><span>High</span><span>Category</span><span>Change</span>
        </div>
        <div style={{ maxHeight:480, overflowY:"auto" }}>
          {filtered.map((p,i) => (
            <div key={p.crop} style={{ display:"grid", gridTemplateColumns:"1.8fr 1fr 1fr 1fr 0.8fr 1fr", padding:"11px 14px", borderBottom:`1px solid ${C.border}`, background:i%2?C.bg:C.white, alignItems:"center" }}>
              <div>
                <span style={{ fontSize:14, fontWeight:500, color:C.text }}>{p.crop}</span>
                <span style={{ fontSize:11, color:C.muted, marginLeft:6 }}>{p.market}</span>
              </div>
              <span style={{ fontSize:14, fontWeight:700, color:C.text }}>₹{p.modal.toLocaleString()}</span>
              <span style={{ fontSize:12.5, color:C.muted }}>₹{p.min.toLocaleString()}</span>
              <span style={{ fontSize:12.5, color:C.muted }}>₹{p.max.toLocaleString()}</span>
              <Badge color={C.muted} bg={C.bg}>{p.category.split(" ")[0]}</Badge>
              <TrendPill trend={p.trend} change={p.change} />
            </div>
          ))}
        </div>
      </Card>

      <Card style={{ background:C.amberPale, border:`1px solid #e0c060` }}>
        <div style={{ fontSize:13, fontWeight:600, color:C.amber, marginBottom:5 }}>💡 AI Market Intelligence</div>
        <div style={{ fontSize:13, color:"#5c4000", lineHeight:1.55 }}>
          <strong>Sell now:</strong> Jasmine (↑10.2%), Green Chilli (↑8.1%), Onion (↑8.1%) — festival season peak.<br/>
          <strong>Hold:</strong> Turmeric (↑4.5%), Cardamom (↑3.2%) — uptrend continuing for 2 more weeks.<br/>
          <strong>Wait:</strong> Toor Dal (↓2.3%), Cotton (↓2.3%) — seasonal correction, hold for 3 weeks.<br/>
          <strong>Best time to sell rice:</strong> Pre-harvest demand — sell stored stocks within 7 days.
        </div>
      </Card>
    </div>
  );
}

export default MarketPrices;
